// Retired codes — do not reuse. Enforced at compile time by the block builders:
// ITP204 (trigger kind not allowed for the block kind), ITP205 (connector direction
// not allowed for the block kind). No longer meaningful since triggers were replaced
// by edges and activation/workload shape moved to the component scaffold: ITP201
// (invalid cron on the trigger-era ScheduleTrigger — its successor for the schedule
// *attribute* introduced by decision 0010 is ITP210), ITP202 (missing trigger),
// ITP203 (multiple TriggeredBy calls).
// Retired with the minimal model (full versions live on the full-topology branch):
// ITP105/ITP106 (connector direction capability — the file transport supports both),
// ITP107 (unresolved connector — every connector now declares its transport),
// ITP501 (API provider — the API surface is not part of the minimal model).

// ITP201 (invalid cron), ITP202 (missing trigger), and ITP203 (multiple TriggeredBy) are
// retired: triggers were replaced by edges and activation/workload shape moved to the
// component scaffold. ITP204/ITP205 (trigger kind / connector direction not allowed for a
// block) are compile errors — the offending methods do not exist on the block's builder
// type. ITP105/ITP106 (connector direction capability), ITP107 (unresolved connector), and
// ITP501 (API provider) retired with the minimal model.

/// <summary>
/// The Aspire run-backend. Discovers a system's validated topology, generates its Dapr
/// components, and translates the model into Aspire resources — one project per component
/// with a Dapr sidecar on its own staged component overlay, and Redis behind pub/sub —
/// then runs it under DCP, subscribers before their publishers. Scheduled components are
/// re-run on their cron ticks by the <see cref="ComponentScheduler"/> (CronJob emulation,
/// with a "Run now" dashboard command). Aspire never sees the topology; it receives
/// ordinary resources.
/// </summary>

edits.newText:
/// <summary>
/// Runs a discovered topology as a local Aspire application with Dapr sidecars. Components
/// start subscribers before publishers when the topic graph is acyclic, and scheduled
/// components run on their cron ticks.
/// </summary>

edits.oldText:
// A deliberately minimal Intropy component worker. It reads the identity and runtime config the
// Aspire run-backend injects, logs them, and exposes an endpoint so its Dapr sidecar has an app to
// talk to. A real worker would use the (future) Intropy Hosting framework to bind subscriptions,
// publishes, and connectors from the same INTROPY__CONFIG contract.

public sealed class OrderFlowSystem : ISystemDefinition
{
    public string SystemName => "order-flow";

    public void Define(SystemBuilder builder)
    {
        // WithSchedule runs ahead of the `intropy sys create` golden template on purpose:
        // CLI codegen does not emit it yet. The extractor runs once at host start and then
        // on every tick; drop "* * * * *" to return to the run-once behavior.
        builder.AddExtractor("order-extractor")
            .From(Connectors.OrderExtractorSource)
            .Publishes(Topics.Orders)
            .WithSchedule("* * * * *");
        builder.AddLoader("order-loader").Subscribes(Topics.Orders).To(Connectors.OrderLoaderDestination);
    }
}

